"use client"

import * as React from "react"
import { Check, Copy, WrapText, X } from "lucide-react"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import styles from "./code-panel.module.css"

export type CodePanelProps = {
  code: string
  filename?: string
  language?: string
  /** Escaped syntax markup generated by the build-time highlighter; never arbitrary remote HTML. */
  highlightedCode?: string
  className?: string
}

export function CodePanel({ code, filename = "example.tsx", language = "tsx", highlightedCode, className }: CodePanelProps) {
  const [wrap, setWrap] = React.useState(false)
  const [confirmation, setConfirmation] = React.useState<"idle" | "copied" | "failed">("idle")
  const timer = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  const mounted = React.useRef(false)
  const copying = React.useRef(false)
  React.useEffect(() => {
    mounted.current = true
    return () => { mounted.current = false; if (timer.current) clearTimeout(timer.current) }
  }, [])
  async function copy() {
    if (copying.current) return
    copying.current = true
    try {
      await navigator.clipboard.writeText(code)
      if (mounted.current) setConfirmation("copied")
    } catch {
      if (mounted.current) setConfirmation("failed")
    } finally {
      copying.current = false
      if (mounted.current) {
        if (timer.current) clearTimeout(timer.current)
        timer.current = setTimeout(() => setConfirmation("idle"), 1600)
      }
    }
  }
  return <div className={cn(styles.panel, className)} data-wrap={wrap}>
    <div className={styles.header}>
      <span className={styles.filename}>{filename}</span>
      <span className={styles.language}>{language}</span>
      <TooltipProvider delayDuration={350}><div className={styles.actions}>
        <Tooltip><TooltipTrigger asChild><button type="button" className={styles.action} aria-label="Wrap long lines" aria-pressed={wrap} onClick={() => setWrap(value => !value)}><WrapText aria-hidden="true" /></button></TooltipTrigger><TooltipContent>Wrap long lines</TooltipContent></Tooltip>
        <Tooltip><TooltipTrigger asChild><button type="button" className={styles.action} data-confirmation={confirmation} aria-label={confirmation === "copied" ? "Code copied" : confirmation === "failed" ? "Copy failed. Select the code to copy manually." : "Copy code"} onClick={copy}><span key={confirmation} className={styles.confirmation}>{confirmation === "copied" ? <Check aria-hidden="true" /> : confirmation === "failed" ? <X aria-hidden="true" /> : <Copy aria-hidden="true" />}</span></button></TooltipTrigger><TooltipContent>Copy code</TooltipContent></Tooltip>
      </div></TooltipProvider>
    </div>
    <div className={styles.codeArea} role="region" aria-label={`${filename} source`}>
      {highlightedCode ? <div dangerouslySetInnerHTML={{ __html: highlightedCode }} /> : <pre tabIndex={0}><code>{code.split("\n").map((line, index, lines) => <React.Fragment key={index}><span className="line">{line}</span>{index < lines.length - 1 ? "\n" : null}</React.Fragment>)}</code></pre>}
    </div>
    <span className={styles.status} role="status">{confirmation === "copied" ? "Code copied to clipboard." : confirmation === "failed" ? "Unable to copy. Select the code and copy it manually." : ""}</span>
  </div>
}
